$ErrorActionPreference='Stop'
$projectRoot=Split-Path $PSScriptRoot -Parent
$screenPath=Join-Path $projectRoot 'src\screens\DownloadedLibraryScreen.tsx'
$text=[IO.File]::ReadAllText($screenPath)
$old="categoryCard:{width:'48.5%',minHeight:64,padding:9,borderRadius:16,borderWidth:1,borderColor:'#DCE9E0',backgroundColor:'#FFF',flexDirection:'row',alignItems:'center'},categoryCardOn:{borderColor:G,backgroundColor:'#0B704B'},categoryIcon:{width:36,height:36,borderRadius:12,backgroundColor:'#E9F6ED',alignItems:'center',justifyContent:'center'},categoryIconOn:{backgroundColor:'#FFF'},categoryLetter:{fontSize:14,fontWeight:'900',color:G},categoryLetterOn:{color:G},categoryCopy:{flex:1,marginLeft:8},categoryTitle:{fontSize:10.5,fontWeight:'800',color:INK},categoryTitleOn:{color:'#FFF'},categoryCount:{marginTop:3,fontSize:8,color:'#7A887F'},categoryCountOn:{color:'#D8F0E1'},categoryArrow:{fontSize:20,color:G},categoryArrowOn:{color:'#FFF'}"
$new="categoryCard:{width:'48.5%',minHeight:148,padding:14,borderRadius:20,borderWidth:1,borderColor:'#D7E7DC',backgroundColor:'#FFF',alignItems:'flex-start',shadowColor:'#174832',shadowOffset:{width:0,height:3},shadowOpacity:.06,shadowRadius:8,elevation:2},categoryCardOn:{borderColor:G,backgroundColor:'#F0FAF3'},categoryIcon:{width:48,height:48,borderRadius:16,backgroundColor:'#E9F6ED',borderWidth:1,borderColor:'#D4EADC',alignItems:'center',justifyContent:'center'},categoryIconOn:{backgroundColor:G,borderColor:G},categoryLetter:{fontSize:16,fontWeight:'900',color:G},categoryLetterOn:{color:'#FFF'},categoryCopy:{width:'100%',marginTop:12},categoryTitle:{fontSize:15,fontWeight:'800',color:INK},categoryTitleOn:{color:G},categoryCount:{marginTop:5,fontSize:9.5,color:'#7A887F'},categoryCountOn:{color:'#4D7A61'},categoryArrow:{position:'absolute',right:14,bottom:12,fontSize:24,color:G},categoryArrowOn:{color:G}"
if(-not $text.Contains($old)){throw 'Compact category card styles were not found.'}
[IO.File]::WriteAllText($screenPath,$text.Replace($old,$new))
